#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s:%d: %s\n",__FILE__,__LINE__,cudaGetErrorString(e));exit(2);}}while(0)
typedef struct __attribute__((packed)){char magic[8];uint32_t version;uint64_t n;uint32_t nf,node_per_step,steps;} Header;
typedef struct{double load,torque,sensitivity;} Qoi;
static int cmpf(const void*a,const void*b){float x=*(const float*)a,y=*(const float*)b;return(x>y)-(x<y);}

BEM_HD void bem_qoi_values(double phi,double vx,double vy,double theta,unsigned node,double *load,double *torque){double cl,cd;bem_polar(bem_node_afid[node],phi-theta,&cl,&cd);double w=(vx*vx+vy*vy)*bem_node_chord[node],s=sin(phi),c=cos(phi);*load=w*cl*c;*torque=w*cl*s*bem_node_r[node];}
BEM_HD Qoi bem_qoi(double phi,double vx,double vy,double theta,unsigned node,double inv_load,double inv_torque){double l,t,lp,tp,lm,tm;bem_qoi_values(phi,vx,vy,theta,node,&l,&t);double h=2e-7;bem_qoi_values(phi+h,vx,vy,theta,node,&lp,&tp);bem_qoi_values(phi-h,vx,vy,theta,node,&lm,&tm);double s=fmax(fabs((lp-lm)/(2*h))*inv_load,fabs((tp-tm)/(2*h))*inv_torque);Qoi q={l,t,s};return q;}
__device__ __forceinline__ void enqueue(uint64_t i,int hard,uint64_t*q,uint32_t*c){unsigned a=__activemask(),m=__ballot_sync(a,hard);if(!hard)return;int lane=threadIdx.x&31,leader=__ffs(m)-1;uint32_t base=0;if(lane==leader)base=atomicAdd(c,(uint32_t)__popc(m));base=__shfl_sync(a,base,leader);unsigned lower=lane?((1u<<lane)-1u):0u;q[base+__popc(m&lower)]=i;}
__global__ void reference_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*root,Qoi*q,uint8_t*ok,uint64_t n,double il,double it){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<n){unsigned node=(unsigned)(i%51)%17;double x;int g=bem_solve_algorithm(vx[i],vy[i],th[i],hint[i],node,4,&x);root[i]=x;q[i]=bem_qoi(x,vx[i],vy[i],th[i],node,il,it);ok[i]=(uint8_t)g;}}
__global__ void select_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*root,double*rho,double*sens,uint8_t*ok,uint8_t*path,uint64_t*q,uint32_t*c,uint64_t n,int method,double eps,double il,double it){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;int hard=0;if(i<n){unsigned node=(unsigned)(i%51)%17;float xf=0;int good=bf_solve((float)vx[i],(float)vy[i],(float)th[i],(float)hint[i],node,512,xf);double witness=NAN;int witnessed=bem_solve_hint_only(vx[i],vy[i],th[i],hint[i],node,&witness);double x=xf,rr=INFINITY;Qoi z=bem_qoi(x,vx[i],vy[i],th[i],node,il,it);double local_tau=method==0?(eps/fmax((double)n*z.sensitivity,1e-300)):eps;BemCertificate a=bem_build_certificate(x,vx[i],vy[i],th[i],node,local_tau,0.0);rr=fmax(a.rho,witnessed?fabs(bem_wrap_pi(x-witness))+5e-10:INFINITY);int pass=good&&witnessed&&a.posterior_pass&&a.branch_pass&&rr<=local_tau;if(pass){path[i]=0;}else{x=bd_refine(xf,vx[i],vy[i],th[i],node);z=bem_qoi(x,vx[i],vy[i],th[i],node,il,it);local_tau=method==0?(eps/fmax((double)n*z.sensitivity,1e-300)):eps;BemCertificate b=bem_build_certificate(x,vx[i],vy[i],th[i],node,local_tau,0.0);rr=fmax(b.rho,witnessed?fabs(bem_wrap_pi(x-witness))+5e-10:INFINITY);pass=good&&witnessed&&b.posterior_pass&&b.branch_pass&&rr<=local_tau;if(pass)path[i]=1;else hard=1;}root[i]=x;rho[i]=rr;sens[i]=z.sensitivity;ok[i]=(uint8_t)(good&&!hard);}enqueue(i,i<n&&hard,q,c);}
__global__ void fallback_kernel(const double*vx,const double*vy,const double*th,const double*hint,double*root,double*rho,double*sens,uint8_t*ok,uint8_t*path,const uint64_t*q,const uint32_t*c,uint64_t n,double il,double it){uint64_t s=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;uint32_t m=*c;if(s<m&&s<n){uint64_t i=q[s];unsigned node=(unsigned)(i%51)%17;double x;int g=bem_solve_algorithm(vx[i],vy[i],th[i],hint[i],node,4,&x);root[i]=x;rho[i]=0;path[i]=2;ok[i]=(uint8_t)g;sens[i]=bem_qoi(x,vx[i],vy[i],th[i],node,il,it).sensitivity;}}
__global__ void qoi_kernel(const double*root,const double*vx,const double*vy,const double*th,Qoi*q,uint64_t n,double il,double it){uint64_t i=(uint64_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<n)q[i]=bem_qoi(root[i],vx[i],vy[i],th[i],(unsigned)(i%51)%17,il,it);}

static void launch(const double*vx,const double*vy,const double*th,const double*hint,double*root,double*rho,double*sens,uint8_t*ok,uint8_t*path,uint64_t*q,uint32_t*c,uint64_t n,int method,double eps,double il,double it){int b=(int)((n+255)/256);CK(cudaMemsetAsync(c,0,sizeof(uint32_t)));select_kernel<<<b,256>>>(vx,vy,th,hint,root,rho,sens,ok,path,q,c,n,method,eps,il,it);fallback_kernel<<<b,256>>>(vx,vy,th,hint,root,rho,sens,ok,path,q,c,n,il,it);}
static long double sum_load(const Qoi*q,size_t n,int which){long double s=0,c=0;for(size_t i=0;i<n;i++){long double x=(which?q[i].torque:q[i].load)-c,t=s+x;c=(t-s)-x;s=t;}return s;}
int main(int argc,char**argv){if(argc<4){fprintf(stderr,"usage: %s dataset.bin method epsilon [repeats] [warmups]\n",argv[0]);return 2;}int method=atoi(argv[2]);double eps=strtod(argv[3],0);int reps=argc>4?atoi(argv[4]):30,warm=argc>5?atoi(argv[5]):10;if(method<0||method>1||eps<=0)return 2;FILE*f=fopen(argv[1],"rb");Header h;if(!f||fread(&h,1,sizeof h,f)!=sizeof h||memcmp(h.magic,"BEMREAL2",8)||h.nf!=5)return 2;size_t db=(size_t)h.n*5*sizeof(double),rb=(size_t)h.n*sizeof(double),sb=(size_t)h.n,qb=(size_t)h.n*sizeof(Qoi);double*hbuf,*hroot,*hrho,*hsens;uint8_t*hflags,*hok,*hpath;Qoi*hq,*hrefq;CK(cudaMallocHost(&hbuf,db));CK(cudaMallocHost(&hroot,rb));CK(cudaMallocHost(&hrho,rb));CK(cudaMallocHost(&hsens,rb));CK(cudaMallocHost(&hflags,sb));CK(cudaMallocHost(&hok,sb));CK(cudaMallocHost(&hpath,sb));CK(cudaMallocHost(&hq,qb));CK(cudaMallocHost(&hrefq,qb));if(fread(hbuf,1,db,f)!=db||fread(hflags,1,sb,f)!=sb)return 2;fclose(f);double*dbuf,*root,*rho,*sens,*refroot;uint8_t*ok,*path;Qoi*qoi,*refq;uint64_t*queue;uint32_t*count;CK(cudaMalloc(&dbuf,db));CK(cudaMalloc(&root,rb));CK(cudaMalloc(&rho,rb));CK(cudaMalloc(&sens,rb));CK(cudaMalloc(&refroot,rb));CK(cudaMalloc(&ok,sb));CK(cudaMalloc(&path,sb));CK(cudaMalloc(&qoi,qb));CK(cudaMalloc(&refq,qb));CK(cudaMalloc(&queue,(size_t)h.n*sizeof(uint64_t)));CK(cudaMalloc(&count,sizeof(uint32_t)));CK(cudaMemcpy(dbuf,hbuf,db,cudaMemcpyHostToDevice));double*vx=dbuf,*vy=vx+h.n,*th=vy+h.n,*hint=dbuf+4*h.n;int blocks=(int)((h.n+255)/256);
  reference_kernel<<<blocks,256>>>(vx,vy,th,hint,refroot,refq,ok,h.n,1,1);CK(cudaDeviceSynchronize());CK(cudaMemcpy(hrefq,refq,qb,cudaMemcpyDeviceToHost));long double ql=sum_load(hrefq,h.n,0),qt=sum_load(hrefq,h.n,1);double il=1.0/fmax(fabs((double)ql),1e-300),it=1.0/fmax(fabs((double)qt),1e-300);reference_kernel<<<blocks,256>>>(vx,vy,th,hint,refroot,refq,ok,h.n,il,it);CK(cudaDeviceSynchronize());CK(cudaMemcpy(hrefq,refq,qb,cudaMemcpyDeviceToHost));ql=sum_load(hrefq,h.n,0);qt=sum_load(hrefq,h.n,1);
  for(int k=0;k<warm;k++)launch(vx,vy,th,hint,root,rho,sens,ok,path,queue,count,h.n,method,eps,il,it);CK(cudaDeviceSynchronize());float*t=(float*)malloc(reps*sizeof(float)),*s=(float*)malloc(reps*sizeof(float));cudaEvent_t a,b;CK(cudaEventCreate(&a));CK(cudaEventCreate(&b));for(int r=0;r<reps;r++){CK(cudaEventRecord(a));launch(vx,vy,th,hint,root,rho,sens,ok,path,queue,count,h.n,method,eps,il,it);qoi_kernel<<<blocks,256>>>(root,vx,vy,th,qoi,h.n,il,it);CK(cudaEventRecord(b));CK(cudaEventSynchronize(b));CK(cudaEventElapsedTime(&t[r],a,b));}CK(cudaMemcpy(hroot,root,rb,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hrho,rho,rb,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hsens,sens,rb,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hok,ok,sb,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hpath,path,sb,cudaMemcpyDeviceToHost));CK(cudaMemcpy(hq,qoi,qb,cudaMemcpyDeviceToHost));size_t pc[3]={0},fail=0;long double bound=0;for(uint64_t i=0;i<h.n;i++){pc[hpath[i]]++;fail+=!hok[i];bound+=(long double)hsens[i]*hrho[i];}long double sl=sum_load(hq,h.n,0),st=sum_load(hq,h.n,1);double el=fabs((double)(sl-ql))/fmax(fabs((double)ql),1e-300),et=fabs((double)(st-qt))/fmax(fabs((double)qt),1e-300);memcpy(s,t,reps*sizeof(float));qsort(s,reps,sizeof(float),cmpf);printf("{\"method\":\"%s\",\"epsilon\":%.17g,\"records\":%" PRIu64 ",\"kernel_qoi_median_ms\":%.9g,\"paths\":{\"fp32\":%zu,\"df32\":%zu,\"fp64\":%zu},\"solver_failures\":%zu,\"predicted_relative_bound\":%.17g,\"actual_load_relative_error\":%.17g,\"actual_torque_relative_error\":%.17g,\"times_ms\":[",method==0?"goal_oriented":"uniform_root_tolerance",eps,h.n,s[reps/2],pc[0],pc[1],pc[2],fail,(double)bound,el,et);for(int r=0;r<reps;r++)printf("%s%.9g",r?",":"",t[r]);printf("]}\n");free(s);free(t);cudaFree(count);cudaFree(queue);cudaFree(refq);cudaFree(qoi);cudaFree(path);cudaFree(ok);cudaFree(refroot);cudaFree(sens);cudaFree(rho);cudaFree(root);cudaFree(dbuf);cudaFreeHost(hrefq);cudaFreeHost(hq);cudaFreeHost(hpath);cudaFreeHost(hok);cudaFreeHost(hflags);cudaFreeHost(hsens);cudaFreeHost(hrho);cudaFreeHost(hroot);cudaFreeHost(hbuf);return fail?3:0;}
